 for(size_t i=0;i<size_t(w)*h;i++)for(int j=0;j<3;j++)source[i*3+j]=float((int(rgba.get()[i*4+j])*rgba.get()[i*4+3]+255*(255-rgba.get()[i*4+3])+127)/255);
 auto axis=[&](const Floats& in,Floats& out,int iw,int ih,int ow,int oh,bool vertical){int old=vertical?ih:iw,count=vertical?oh:ow,other=vertical?ow:oh;double ratio=double(old)/count,support=2*std::max(1.,ratio);
  for(int i=0;i<count;i++){double center=(i+.5)*ratio;int begin=std::max(0,int(std::floor(center-support+.5))),end=std::min(old,int(std::floor(center+support+.5)));Floats weights;double sum=0;for(int j=begin;j<end;j++){float a=cubic(float((j+.5-center)/std::max(1.,ratio)));weights.push_back(a);sum+=a;}require(std::abs(sum)>1e-8,"Invalid material interpolation");for(int k=0;k<other;k++)for(int ch=0;ch<3;ch++){double value=0;for(int j=begin;j<end;j++){size_t at=vertical?(size_t(j)*iw+k)*3+ch:(size_t(k)*iw+j)*3+ch;value+=in[at]*weights[j-begin]/sum;}size_t at=vertical?(size_t(i)*ow+k)*3+ch:(size_t(k)*ow+i)*3+ch;out[at]=std::round(std::clamp(value,0.,255.));}}
 };
