inline Floats chw(const Floats& rgb,int size,bool normalize){require(rgb.size()==size_t(size)*size*3,"Material image shape mismatch");Floats result(rgb.size());for(size_t i=0;i<size_t(size)*size;i++)for(int c=0;c<3;c++)result[size_t(c)*size*size+i]=normalize?rgb[i*3+c]*2-1:rgb[i*3+c];return result;}
inline Floats hwc(const Floats& image,int size){require(image.size()==size_t(size)*size*3,"Generated image shape mismatch");Floats result(image.size());for(size_t i=0;i<size_t(size)*size;i++)for(int c=0;c<3;c++)result[i*3+c]=std::clamp(image[size_t(c)*size*size+i],0.f,1.f);return result;}
inline int material_dimension(const json& c,const char* key,int lo,int hi){require(c.at(key).is_number_integer(),"Material dimension must be integer");int64_t v=c.at(key);require(v>=lo&&v<=hi,"Material dimension outside bounds");return int(v);}
